import React, { useCallback, useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { useAuth } from "@/components/auth/EmailGate";
import { Button } from "@/components/ui/button";
import { Loader2, BookOpen, AlertCircle } from "lucide-react";
import SopBrowser from "@/components/sop/SopBrowser";
import SopDetail from "@/components/sop/SopDetail";
import SopEditor from "@/components/sop/SopEditor";
import SopAdminPanel from "@/components/sop/SopAdminPanel";
import SopPrint, { SOP_PRINT_CSS } from "@/components/sop/SopPrint";
import AiSopBuilderDialog from "@/components/sop/AiSopBuilderDialog";
import SopRunMode from "@/components/sop/SopRunMode";
import SopQrDialog from "@/components/sop/SopQr";
import {
  sopBootstrap, sopCreate, sopUpdate, sopSetStatus, sopDelete, sopAcknowledge, sopSuggestEdit, sopResolveSuggestion,
} from "@/components/sop/sopService";
import { newSopDraft } from "@/components/sop/sopModel";

// The SOP module front page: browse procedures by department, read them with
// photos/video, and — for admins and named editors — build new ones with AI
// assist (dictation, notes-to-draft, per-step polish, photo-to-step). All
// persistence goes through the session-authenticated manageSops function.

export default function SOP() {
  const { currentUser } = useAuth();
  const [searchParams, setSearchParams] = useSearchParams();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [settings, setSettings] = useState(null);
  const [settingsDate, setSettingsDate] = useState("");
  const [sops, setSops] = useState([]);
  const [me, setMe] = useState(null);
  const [view, setView] = useState("browse"); // browse | detail | edit
  const [activeSop, setActiveSop] = useState(null);
  const [isNewDraft, setIsNewDraft] = useState(false);
  const [draftEpoch, setDraftEpoch] = useState(0);
  const [adminOpen, setAdminOpen] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [printSop, setPrintSop] = useState(null);
  const [runSop, setRunSop] = useState(null);
  const [qrSop, setQrSop] = useState(null);
  const [busy, setBusy] = useState(false);
  const [acknowledging, setAcknowledging] = useState(false);

  const categoryParam = searchParams.get("category") || "all";

  const bootstrap = useCallback(async () => {
    try {
      const res = await sopBootstrap();
      setSettings(res?.settings || null);
      setSettingsDate(res?.settings_updated_date || "");
      setSops(Array.isArray(res?.sops) ? res.sops : []);
      setMe(res?.me || null);
      setError("");
    } catch (e) {
      setError(e?.message || "Could not load SOPs.");
    }
    setLoading(false);
  }, []);

  useEffect(() => { bootstrap(); }, [bootstrap]);

  // Deep links: ?sop=<id> opens detail, ?edit=<id> opens the editor.
  useEffect(() => {
    if (loading) return;
    const sopId = searchParams.get("sop");
    const editId = searchParams.get("edit");
    if (editId) {
      const found = sops.find((s) => s.id === editId);
      if (found) { setActiveSop(found); setIsNewDraft(false); setView("edit"); }
    } else if (sopId) {
      const found = sops.find((s) => s.id === sopId);
      if (found) { setActiveSop(found); setView("detail"); }
    }
  }, [loading, sops, searchParams]);

  const setParam = (key, value) => {
    const next = new URLSearchParams(searchParams);
    if (value) next.set(key, value); else next.delete(key);
    setSearchParams(next, { replace: true });
  };

  const setParams = (entries) => {
    const next = new URLSearchParams(searchParams);
    for (const [key, value] of Object.entries(entries)) {
      if (value) next.set(key, value); else next.delete(key);
    }
    setSearchParams(next, { replace: true });
  };

  const openDetail = (sop) => {
    setActiveSop(sop);
    setView("detail");
    setParams({ sop: sop.id, edit: "" });
  };

  const goBrowse = () => {
    setView("browse");
    setActiveSop(null);
    const next = new URLSearchParams(searchParams);
    next.delete("sop");
    next.delete("edit");
    setSearchParams(next, { replace: true });
  };

  const startNew = () => {
    setActiveSop(newSopDraft(settings, currentUser));
    setIsNewDraft(true);
    setDraftEpoch((n) => n + 1);
    setView("edit");
  };

  const startEdit = (sop) => {
    setActiveSop(sop);
    setIsNewDraft(false);
    setDraftEpoch((n) => n + 1);
    setView("edit");
    setParams({ edit: sop.id, sop: "" });
  };

  const applyAiDraft = (draft) => {
    const editingExisting = view === "edit" && !isNewDraft && activeSop?.id;
    const base = editingExisting ? { ...activeSop } : newSopDraft(settings, currentUser);
    setActiveSop({
      ...base,
      title: draft.title || base.title,
      category: draft.category || base.category,
      summary: draft.summary || base.summary,
      estimated_minutes: draft.estimated_minutes || base.estimated_minutes,
      safety_notes: draft.safety_notes?.length ? draft.safety_notes : base.safety_notes,
      steps: draft.steps?.length ? draft.steps : base.steps,
    });
    if (!editingExisting) setIsNewDraft(true);
    setDraftEpoch((n) => n + 1);
    setView("edit");
  };

  const persist = async (payload, publish = false) => {
    setBusy(true);
    try {
      if (isNewDraft) {
        const created = await sopCreate(payload);
        let record = created?.record;
        if (publish && record?.id) {
          const res = await sopSetStatus({ id: record.id, expectedUpdatedDate: record.updated_date, status: "published" });
          record = res?.record || record;
        }
        await bootstrap();
        if (record?.id) {
          setActiveSop(record);
          setIsNewDraft(false);
          setView("detail");
          setParams({ sop: record.id, edit: "" });
        } else {
          goBrowse();
        }
      } else {
        const res = await sopUpdate({ id: activeSop.id, expectedUpdatedDate: activeSop.updated_date, nextFields: payload });
        let record = res?.record;
        if (publish && record?.status !== "published") {
          const st = await sopSetStatus({ id: record.id, expectedUpdatedDate: record.updated_date, status: "published" });
          record = st?.record || record;
        }
        await bootstrap();
        if (record?.id) {
          setActiveSop(record);
          setView("detail");
          setParams({ sop: record.id, edit: "" });
        } else {
          goBrowse();
        }
      }
      setError("");
      setBusy(false);
      return true;
    } catch (e) {
      setError(e?.message || "Could not save the SOP.");
      setBusy(false);
      return false;
    }
  };

  const archiveSop = async (sop) => {
    setBusy(true);
    try {
      await sopSetStatus({ id: sop.id, expectedUpdatedDate: sop.updated_date, status: "archived" });
      await bootstrap();
      goBrowse();
    } catch (e) {
      setError(e?.message || "Could not archive the SOP.");
    }
    setBusy(false);
  };

  const deleteSop = async (sop) => {
    if (!window.confirm(`Delete "${sop.title}" permanently? This cannot be undone.`)) return;
    setBusy(true);
    try {
      await sopDelete({ id: sop.id, expectedUpdatedDate: sop.updated_date });
      await bootstrap();
      goBrowse();
    } catch (e) {
      setError(e?.message || "Could not delete the SOP.");
    }
    setBusy(false);
  };

  const cloneSop = (sop) => {
    const { id, updated_date, created_date, acknowledged_viewers, suggestions, status, ...rest } = sop;
    setActiveSop({ ...rest, title: `Copy of ${sop.title}`, status: "draft", version: 1 });
    setIsNewDraft(true);
    setDraftEpoch((n) => n + 1);
    setView("edit");
  };

  const sendSuggestion = async ({ sopId, stepId, text }) => {
    try {
      await sopSuggestEdit({ id: sopId, stepId, text });
      setError("");
    } catch (e) {
      setError(e?.message || "Could not send your suggestion.");
    }
  };

  const resolveSuggestion = async ({ sop, suggestionId, outcome }) => {
    try {
      await sopResolveSuggestion({ id: sop.id, suggestionId, outcome, expectedUpdatedDate: sop.updated_date });
      await bootstrap();
    } catch (e) {
      setError(e?.message || "Could not update that suggestion.");
    }
  };

  // Bulk card actions from the browser's select mode — per-item try/catch so
  // one stale row doesn't abort the rest.
  const bulkUpdate = async ({ ids, action, category }) => {
    setBusy(true);
    for (const id of ids || []) {
      const sop = sops.find((s) => s.id === id);
      if (!sop) continue;
      try {
        if (action === "publish" || action === "archive") {
          await sopSetStatus({ id, expectedUpdatedDate: sop.updated_date, status: action === "publish" ? "published" : "archived" });
        } else if (action === "pin" || action === "unpin") {
          await sopUpdate({ id, expectedUpdatedDate: sop.updated_date, nextFields: { pinned: action === "pin" } });
        } else if (action === "move" && category) {
          await sopUpdate({ id, expectedUpdatedDate: sop.updated_date, nextFields: { category } });
        }
      } catch (e) {
        setError(e?.message || `Could not update "${sop.title}".`);
      }
    }
    await bootstrap();
    setBusy(false);
  };

  const acknowledge = async (sop) => {
    setAcknowledging(true);
    try {
      const res = await sopAcknowledge(sop.id);
      const updated = res?.sop;
      await bootstrap();
      if (updated?.id) setActiveSop(updated);
    } catch (e) {
      setError(e?.message || "Could not save your acknowledgment.");
    }
    setAcknowledging(false);
  };

  if (loading) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-slate-400" />
      </div>
    );
  }

  return (
    <div className="p-4 sm:p-6 max-w-7xl mx-auto">
      <style>{SOP_PRINT_CSS}</style>

      <div className="flex items-center gap-3 mb-5">
        <BookOpen className="h-7 w-7 text-slate-700" />
        <div>
          <h1 className="text-2xl font-bold text-slate-900">SOPs</h1>
          <p className="text-sm text-slate-500">Standard operating procedures — how we do things in this shop.</p>
        </div>
      </div>

      {error && (
        <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 flex items-start gap-2 text-sm text-red-700">
          <AlertCircle className="h-4 w-4 mt-0.5 shrink-0" />
          <span className="flex-1">{error}</span>
          <Button type="button" size="sm" variant="ghost" onClick={bootstrap}>Retry</Button>
        </div>
      )}

      {view === "browse" && (
        <SopBrowser
          sops={sops}
          settings={settings}
          me={me}
          activeCategory={categoryParam}
          onCategoryChange={(key) => setParam("category", key === "all" ? "" : key)}
          onOpen={openDetail}
          onNew={startNew}
          onAiBuild={() => setAiOpen(true)}
          onAdmin={() => setAdminOpen(true)}
          onBulk={bulkUpdate}
        />
      )}

      {view === "detail" && activeSop && (
        <SopDetail
          sop={sops.find((s) => s.id === activeSop.id) || activeSop}
          settings={settings}
          me={me}
          onBack={goBrowse}
          onEdit={startEdit}
          onAcknowledge={acknowledge}
          onPrint={setPrintSop}
          onRun={setRunSop}
          onQr={setQrSop}
          onClone={cloneSop}
          onSuggest={sendSuggestion}
          acknowledging={acknowledging}
        />
      )}

      {view === "edit" && activeSop && (
        <SopEditor
          key={`${isNewDraft ? "new" : activeSop.id}-${draftEpoch}`}
          sop={activeSop}
          settings={settings}
          me={me}
          isNew={isNewDraft}
          saving={busy}
          onCancel={isNewDraft ? goBrowse : () => openDetail(activeSop)}
          onSave={(payload) => persist(payload, false)}
          onPublish={(payload) => persist(payload, true)}
          onArchive={archiveSop}
          onDelete={deleteSop}
          onAiBuild={() => setAiOpen(true)}
        />
      )}

      <AiSopBuilderDialog
        open={aiOpen}
        onClose={() => setAiOpen(false)}
        categories={settings?.categories || []}
        settings={settings}
        onApply={applyAiDraft}
      />

      <SopAdminPanel
        open={adminOpen}
        onClose={() => setAdminOpen(false)}
        settings={settings}
        settingsUpdatedDate={settingsDate}
        sops={sops}
        onSaved={(next, nextDate) => { setSettings(next); setSettingsDate(nextDate); }}
        onResolveSuggestion={resolveSuggestion}
      />

      {printSop && (
        <SopPrint sop={printSop} settings={settings} onClose={() => setPrintSop(null)} />
      )}

      {runSop && (
        <SopRunMode sop={runSop} settings={settings} onClose={() => setRunSop(null)} />
      )}

      <SopQrDialog sop={qrSop} settings={settings} open={!!qrSop} onClose={() => setQrSop(null)} />
    </div>
  );
}

import React, { useEffect, useMemo, useState } from "react";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from "@/components/ui/sheet";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Plus, Trash2, X, Loader2, Save, Users, MessageSquarePlus } from "lucide-react";
import { sopSaveSettings, sopAckReport } from "./sopService";

// Admin drawer: department categories, named SOP editors, module defaults,
// and the read-receipt report. Saves go through manageSops save_settings
// (admin-only server-side).

const slugify = (s) => String(s || "").toLowerCase().trim().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "").slice(0, 40);

function CategoryRow({ cat, inUse, onChange, onRemove }) {
  return (
    <div className="flex items-center gap-2">
      <input
        type="color"
        value={/^#[0-9a-fA-F]{6}$/.test(cat.color) ? cat.color : "#94A3B8"}
        onChange={(e) => onChange({ ...cat, color: e.target.value })}
        className="h-8 w-10 rounded border cursor-pointer"
        title="Category color"
      />
      <Input value={cat.label} onChange={(e) => onChange({ ...cat, label: e.target.value, key: cat.key === slugify(cat.label) ? slugify(e.target.value) : cat.key })} className="h-8" />
      <span className="text-[10px] text-slate-400 w-20 truncate" title={cat.key}>{cat.key}</span>
      {inUse > 0 && <Badge variant="outline" className="text-[10px]">{inUse} SOP{inUse === 1 ? "" : "s"}</Badge>}
      <Button
        type="button" variant="ghost" size="icon"
        onClick={onRemove}
        disabled={cat.key === "other" || inUse > 0}
        title={cat.key === "other" ? "The 'other' category is required" : inUse > 0 ? "Reassign SOPs to another category first" : "Remove category"}
        className="h-8 w-8 shrink-0 text-slate-400 hover:text-red-600"
      >
        <Trash2 className="h-4 w-4" />
      </Button>
    </div>
  );
}

export default function SopAdminPanel({ open, onClose, settings, settingsUpdatedDate, sops, onSaved, onResolveSuggestion }) {
  const [form, setForm] = useState(null);
  const [editorInput, setEditorInput] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [report, setReport] = useState(null);
  const [reportBusy, setReportBusy] = useState(false);
  const [expandedReport, setExpandedReport] = useState("");

  useEffect(() => {
    if (open) {
      setForm(settings ? JSON.parse(JSON.stringify(settings)) : null);
      setError("");
      setReport(null);
    }
  }, [open, settings]);

  const inUseByCategory = useMemo(() => {
    const map = {};
    for (const sop of sops || []) map[sop.category] = (map[sop.category] || 0) + 1;
    return map;
  }, [sops]);

  // Staff-submitted edit suggestions still marked "open", newest first.
  const openSuggestions = useMemo(() => {
    const list = [];
    for (const sop of sops || []) {
      for (const sug of sop.suggestions || []) {
        if (sug?.status === "open") list.push({ sop, sug });
      }
    }
    return list.sort((a, b) => String(b.sug.created_at || "").localeCompare(String(a.sug.created_at || "")));
  }, [sops]);

  const patch = (fields) => setForm((f) => ({ ...f, ...fields }));
  const patchCategory = (i, next) => patch({ categories: form.categories.map((c, idx) => (idx === i ? next : c)) });

  const addCategory = () => {
    const label = `New department`;
    let key = slugify(label);
    let n = 1;
    while (form.categories.some((c) => c.key === key)) { n += 1; key = slugify(`${label}_${n}`); }
    patch({ categories: [...form.categories, { key, label, color: "#94A3B8", icon: "Folder" }] });
  };

  const removeCategory = (i) => {
    const cat = form.categories[i];
    if (!cat || cat.key === "other" || (inUseByCategory[cat.key] || 0) > 0) return;
    patch({ categories: form.categories.filter((_, idx) => idx !== i) });
  };

  const addEditor = () => {
    const email = editorInput.trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { setError("Enter a valid email for the editor."); return; }
    patch({ editor_emails: [...new Set([...(form.editor_emails || []), email])] });
    setEditorInput("");
    setError("");
  };

  const save = async () => {
    setSaving(true);
    setError("");
    try {
      const res = await sopSaveSettings({ settings: form, expectedUpdatedDate: settingsUpdatedDate });
      onSaved?.(res?.settings || form, res?.settings_updated_date || "");
      onClose?.();
    } catch (e) {
      setError(e?.message || "Could not save SOP settings.");
    }
    setSaving(false);
  };

  const loadReport = async () => {
    setReportBusy(true);
    try {
      const res = await sopAckReport();
      setReport(res?.report || []);
    } catch (e) {
      setError(e?.message || "Could not load the acknowledgment report.");
    }
    setReportBusy(false);
  };

  if (!form) return null;

  return (
    <Sheet open={open} onOpenChange={(v) => { if (!v) onClose?.(); }}>
      <SheetContent side="right" className="w-full sm:max-w-xl overflow-y-auto">
        <SheetHeader>
          <SheetTitle>SOP settings</SheetTitle>
          <SheetDescription>Departments, who can edit, defaults, and read receipts.</SheetDescription>
        </SheetHeader>

        <Tabs defaultValue="categories" className="mt-4">
          <TabsList className="grid w-full grid-cols-5">
            <TabsTrigger value="categories">Departments</TabsTrigger>
            <TabsTrigger value="editors">Editors</TabsTrigger>
            <TabsTrigger value="defaults">Defaults</TabsTrigger>
            <TabsTrigger value="suggestions" className="gap-1">
              Suggest
              {openSuggestions.length > 0 && (
                <Badge variant="secondary" className="bg-amber-100 text-amber-800 px-1.5">{openSuggestions.length}</Badge>
              )}
            </TabsTrigger>
            <TabsTrigger value="acks" onClick={() => { if (!report && !reportBusy) loadReport(); }}>Receipts</TabsTrigger>
          </TabsList>

          <TabsContent value="categories" className="space-y-3 pt-3">
            <p className="text-xs text-slate-500">Departments group SOPs on the main page. A department can't be removed while SOPs still use it.</p>
            <div className="space-y-2">
              {form.categories.map((cat, i) => (
                <CategoryRow
                  key={cat.key || i}
                  cat={cat}
                  inUse={inUseByCategory[cat.key] || 0}
                  onChange={(next) => patchCategory(i, next)}
                  onRemove={() => removeCategory(i)}
                />
              ))}
            </div>
            <Button type="button" variant="outline" size="sm" onClick={addCategory} className="gap-1.5">
              <Plus className="h-4 w-4" /> Add department
            </Button>
          </TabsContent>

          <TabsContent value="editors" className="space-y-3 pt-3">
            <p className="text-xs text-slate-500">Admins can always edit. Add staff emails here to let them create and edit SOPs too.</p>
            <div className="flex gap-2">
              <Input
                value={editorInput}
                onChange={(e) => setEditorInput(e.target.value)}
                onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); addEditor(); } }}
                placeholder="lead@company.com"
                className="h-9"
              />
              <Button type="button" variant="outline" size="sm" onClick={addEditor} className="gap-1">
                <Plus className="h-4 w-4" /> Add
              </Button>
            </div>
            <div className="flex flex-wrap gap-1.5">
              {(form.editor_emails || []).map((email) => (
                <Badge key={email} variant="secondary" className="gap-1">
                  {email}
                  <button type="button" onClick={() => patch({ editor_emails: form.editor_emails.filter((e) => e !== email) })}>
                    <X className="h-3 w-3" />
                  </button>
                </Badge>
              ))}
              {!(form.editor_emails || []).length && <p className="text-xs text-slate-400">No named editors yet — only admins can edit.</p>}
            </div>
          </TabsContent>

          <TabsContent value="defaults" className="space-y-4 pt-3">
            <label className="flex items-center justify-between gap-3 rounded-lg border p-3">
              <span className="text-sm">
                <span className="font-medium">Require read receipt by default</span>
                <span className="block text-xs text-slate-500">New SOPs start with "I have read this" turned on.</span>
              </span>
              <Switch checked={form.require_ack_default === true} onCheckedChange={(v) => patch({ require_ack_default: v })} />
            </label>
            <label className="flex items-center justify-between gap-3 rounded-lg border p-3">
              <span className="text-sm">
                <span className="font-medium">Allow in-app camera &amp; mic</span>
                <span className="block text-xs text-slate-500">Photo snapshot, video recording, and voice dictation controls.</span>
              </span>
              <Switch checked={form.allow_in_app_recording !== false} onCheckedChange={(v) => patch({ allow_in_app_recording: v })} />
            </label>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Max image size (MB)</Label>
                <Input type="number" min={1} max={100} value={form.max_image_upload_mb} onChange={(e) => patch({ max_image_upload_mb: e.target.value })} />
              </div>
              <div>
                <Label>Max video size (MB)</Label>
                <Input type="number" min={1} max={500} value={form.max_video_upload_mb} onChange={(e) => patch({ max_video_upload_mb: e.target.value })} />
              </div>
            </div>
          </TabsContent>

          <TabsContent value="suggestions" className="space-y-3 pt-3">
            <p className="text-xs text-slate-500">Edit suggestions submitted by staff on published SOPs. Resolve marks them handled; dismiss hides them.</p>
            {openSuggestions.length === 0 ? (
              <div className="rounded-lg border border-dashed border-slate-300 bg-slate-50 py-10 text-center">
                <MessageSquarePlus className="h-8 w-8 mx-auto text-slate-300" />
                <p className="mt-2 text-sm text-slate-400">No open suggestions right now.</p>
              </div>
            ) : (
              openSuggestions.map(({ sop, sug }) => {
                const stepIdx = (sop.steps || []).findIndex((st) => st.id === sug.step_id);
                const step = stepIdx >= 0 ? sop.steps[stepIdx] : null;
                return (
                  <div key={sug.id} className="rounded-lg border p-3 space-y-2">
                    <div className="flex items-start justify-between gap-2">
                      <div className="min-w-0">
                        <p className="text-sm font-medium truncate">{sop.title}</p>
                        <p className="text-xs text-slate-500">
                          {step ? `Step ${stepIdx + 1}${step.title ? ` — ${step.title}` : ""}` : "General"}
                          {" · "}{sug.name || sug.email || "Someone"}
                          {sug.created_at ? ` · ${new Date(sug.created_at).toLocaleDateString()}` : ""}
                        </p>
                      </div>
                      <Badge variant="secondary" className="bg-amber-100 text-amber-800 shrink-0">open</Badge>
                    </div>
                    <p className="text-sm text-slate-700 whitespace-pre-wrap">{sug.text}</p>
                    <div className="flex justify-end gap-2">
                      <Button type="button" variant="outline" size="sm" onClick={() => onResolveSuggestion?.({ sop, suggestionId: sug.id, outcome: "dismissed" })}>Dismiss</Button>
                      <Button type="button" size="sm" onClick={() => onResolveSuggestion?.({ sop, suggestionId: sug.id, outcome: "resolved" })}>Resolve</Button>
                    </div>
                  </div>
                );
              })
            )}
          </TabsContent>

          <TabsContent value="acks" className="space-y-3 pt-3">
            <div className="flex items-center justify-between">
              <p className="text-xs text-slate-500">Who has acknowledged the current version of each receipt-required SOP.</p>
              <Button type="button" variant="ghost" size="sm" onClick={loadReport} disabled={reportBusy} className="gap-1 h-7 text-xs">
                {reportBusy ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : null} Refresh
              </Button>
            </div>
            {reportBusy && !report && <p className="text-sm text-slate-400 flex items-center gap-2"><Loader2 className="h-4 w-4 animate-spin" /> Loading…</p>}
            {report && report.length === 0 && (
              <p className="text-sm text-slate-400">No published SOPs require read receipts yet.</p>
            )}
            {report && report.map((row) => (
              <div key={row.sop_id} className="rounded-lg border p-3">
                <button type="button" className="w-full flex items-center justify-between gap-2 text-left" onClick={() => setExpandedReport((cur) => (cur === row.sop_id ? "" : row.sop_id))}>
                  <span className="text-sm font-medium truncate">{row.title} <span className="text-xs text-slate-400">v{row.version}</span></span>
                  <span className="flex items-center gap-1.5 text-xs shrink-0">
                    <Badge variant="secondary" className="bg-emerald-100 text-emerald-800">{row.acknowledged.length} read</Badge>
                    <Badge variant="secondary" className={row.pending.length ? "bg-red-100 text-red-700" : ""}>{row.pending.length} pending</Badge>
                  </span>
                </button>
                {expandedReport === row.sop_id && (
                  <div className="mt-2 grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs">
                    <div>
                      <p className="font-semibold text-emerald-700 mb-1">Acknowledged</p>
                      {row.acknowledged.length ? row.acknowledged.map((a) => (
                        <p key={a.email} className="text-slate-600">{a.name || a.email} · {a.at ? new Date(a.at).toLocaleDateString() : ""}</p>
                      )) : <p className="text-slate-400">Nobody yet</p>}
                    </div>
                    <div>
                      <p className="font-semibold text-red-700 mb-1 flex items-center gap-1"><Users className="h-3.5 w-3.5" /> Pending</p>
                      {row.pending.length ? row.pending.map((p) => (
                        <p key={p.email} className="text-slate-600">{p.name || p.email}</p>
                      )) : <p className="text-slate-400">Everyone is current</p>}
                    </div>
                  </div>
                )}
              </div>
            ))}
          </TabsContent>
        </Tabs>

        {error && <p className="mt-3 text-sm text-red-600">{error}</p>}
        <div className="sticky bottom-0 mt-4 -mx-6 border-t bg-white/95 backdrop-blur px-6 py-3 flex justify-end gap-2">
          <Button type="button" variant="ghost" onClick={onClose}>Cancel</Button>
          <Button type="button" onClick={save} disabled={saving} className="gap-1.5">
            {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />} Save settings
          </Button>
        </div>
      </SheetContent>
    </Sheet>
  );
}
